mapper.select:
select FILETYPEID, PARENTTYPEID, FILETYPENAME, TREELEVEL, (select count(1) from dj_workresourcelibrarytype l where l.PARENTTYPEID=f.FILETYPEID) as CHILDCOUNT from dj_workresourcelibrarytype f where 1=1
and f.PARENTTYPEID = #{ pFileId }
and f.FILETYPENAME like '%'||#{typename}||'%'
and f.PARENTTYPEID is null
and f.FILETYPEID in
#{typeId}
and f.FILETYPEID not in
#{typeId}
order by treelevel asc

select f.*,ft.FILETYPENAME,ft.TREELEVEL from ( select t.*,fn_FileTypeRoot(t.FILETYPEID) as rootTypeId from dj_workresourcelibrary t where 1=1
and t.fileName like concat('%',#{fileName},'%')
and t.FILETYPEID in
#{typeId}
) f inner join dj_workresourcelibrarytype ft on f.rootTypeId=ft.FILETYPEID
